export const NATIONWIDE_LAYER_TEXT = NATIONWIDE_PAGES.join('\n');

export function nationwideTextLayer() {
  let line = 0;
  const pageLineRanges = NATIONWIDE_PAGES.map((p, i) => {
    const startLine = line;
    const endLine = startLine + p.split('\n').length - 1;
    line = endLine + 1;
    return { page: i + 1, startLine, endLine };
  });
  return {
    text: NATIONWIDE_LAYER_TEXT,
    pageCount: NATIONWIDE_PAGES.length,
    available: true,
    pageLineRanges,
  };
}
